#ifndef CP_ALGO_LINALG_BLOCK_INVERSE_HPP
#define CP_ALGO_LINALG_BLOCK_INVERSE_HPP
#include "matrix.hpp"
namespace cp_algo::linalg{ template<class base,class row> std::pair<base,matrix<base,row>>block_inverse(matrix<base,row>const&A){ assert(A.n()==A.m()); using matrix=linalg::matrix<base,row>; if constexpr(impl::use_strassen<row>){ if(A.n()>=128){ auto lo=std::views::take(A.n()/2); auto hi=std::views::drop(A.n()/2); auto[da,ai] =block_inverse(matrix(A.submatrix(lo,lo))); if(da!=base(0)){ matrix b=A.submatrix(lo,hi),c=A.submatrix(hi,lo),d=A.submatrix(hi,hi); b.normalize();c.normalize();d.normalize(); auto mul= [](matrix const&x,matrix const&y){ return impl::strassen_product<base::mod()>::product(x,y); }; auto v=mul(c,ai); d-=mul(v,b); auto[ds,si] =block_inverse(d); if(ds==base(0))return{0,{}}; auto u=mul(ai,b); auto r=mul(u,si),t=mul(si,v); ai+=mul(r,v); matrix res(A.n()); res.assign_submatrix(lo,lo,ai); res.assign_submatrix(lo,hi,-r); res.assign_submatrix(hi,lo,-t); res.assign_submatrix(hi,hi,si); return{da*ds,std::move(res)}; } } matrix b(A.submatrix(std::views::all,std::views::all)); big_vector<size_t>swaps(A.n()); base det=1; for(size_t i=0;i<A.n();i++){ size_t p=i; while(p<A.n()&&b[p].normalize(i)==base(0))p++; if(p==A.n())return{0,{}}; swaps[i] =p; if(p!=i){std::swap(b[p],b[i]);det= -det;} b[i].normalize(); using small=math::modint<int(base::mod())>; base inv=small(b[i][i].getr()).inv().getr(); det*=b[i][i]; b[i][i] =1; for(auto&x:b[i])x.setr(uint64_t(x.getr())*inv.getr()%base::mod()); for(size_t j=0;j<A.n();j++)if(j!=i){ base scale= -b[j].normalize(i); b[j][i] =0; b[j].add_scaled(b[i],scale); } } for(size_t i=A.n();i-- >0;){ if(swaps[i] !=i)for(auto&values:b)std::swap(values[i],values[swaps[i]]); } b.normalize(); return{det,std::move(b)}; } return A.inv(); } }
#endif
